import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

triplet_loss_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 512

__global__ void triplet_margin_loss_kernel(
    const float* __restrict__ anchor,
    const float* __restrict__ positive,
    const float* __restrict__ negative,
    float* __restrict__ per_row_loss,
    const int batch_size,
    const int dim,
    const float margin)
{
    int row = blockIdx.x;
    if (row >= batch_size) return;
    const float* a_row = anchor + (size_t)row * dim;
    const float* p_row = positive + (size_t)row * dim;
    const float* n_row = negative + (size_t)row * dim;
    float sum_pos = 0.0f;
    float sum_neg = 0.0f;
    int dim4 = dim / 4;
    const float4* a4 = reinterpret_cast<const float4*>(a_row);
    const float4* p4 = reinterpret_cast<const float4*>(p_row);
    const float4* n4 = reinterpret_cast<const float4*>(n_row);
    for (int i = threadIdx.x; i < dim4; i += blockDim.x) {
        float4 av = a4[i];
        float4 pv = p4[i];
        float4 nv = n4[i];
        float dp0 = av.x - pv.x;
        float dp1 = av.y - pv.y;
        float dp2 = av.z - pv.z;
        float dp3 = av.w - pv.w;
        float dn0 = av.x - nv.x;
        float dn1 = av.y - nv.y;
        float dn2 = av.z - nv.z;
        float dn3 = av.w - nv.w;
        sum_pos += dp0 * dp0 + dp1 * dp1 + dp2 * dp2 + dp3 * dp3;
        sum_neg += dn0 * dn0 + dn1 * dn1 + dn2 * dn2 + dn3 * dn3;
    }
    for (int i = dim4 * 4 + threadIdx.x; i < dim; i += blockDim.x) {
        float a = a_row[i];
        float p = p_row[i];
        float n = n_row[i];
        float dp = a - p;
        float dn = a - n;
        sum_pos += dp * dp;
        sum_neg += dn * dn;
    }
    // Warp-level reduction using shuffle instructions to avoid heavy shared-memory traffic
    unsigned int mask = 0xffffffff;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum_pos += __shfl_down_sync(mask, sum_pos, offset);
        sum_neg += __shfl_down_sync(mask, sum_neg, offset);
    }
    __shared__ float shared_pos[BLOCK_SIZE / 32];
    __shared__ float shared_neg[BLOCK_SIZE / 32];
    int warp_id = threadIdx.x / 32;
    int lane_id = threadIdx.x % 32;
    if (lane_id == 0) {
        shared_pos[warp_id] = sum_pos;
        shared_neg[warp_id] = sum_neg;
    }
    __syncthreads();
    if (warp_id == 0) {
        float p = (lane_id < (BLOCK_SIZE / 32)) ? shared_pos[lane_id] : 0.0f;
        float n = (lane_id < (BLOCK_SIZE / 32)) ? shared_neg[lane_id] : 0.0f;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            p += __shfl_down_sync(mask, p, offset);
            n += __shfl_down_sync(mask, n, offset);
        }
        if (lane_id == 0) {
            float dist_pos = sqrtf(p);
            float dist_neg = sqrtf(n);
            float loss = dist_pos - dist_neg + margin;
            loss = loss > 0.0f ? loss : 0.0f;
            // Store per-row loss instead of a global atomicAdd to avoid
            // heavy atomic contention across a huge number of blocks.
            per_row_loss[row] = loss;
        }
    }
}
#define REDUCE_BLOCK_SIZE 128
__global__ void reduce_sum_kernel(
    const float* __restrict__ per_row_loss,
    float* __restrict__ loss_sum,
    const int n)
{
    __shared__ float sdata[REDUCE_BLOCK_SIZE];
    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;
    float sum = 0.0f;
    for (int i = idx; i < n; i += blockDim.x * gridDim.x) {
        sum += per_row_loss[i];
    }
    sdata[tid] = sum;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }
    if (tid == 0) {
        atomicAdd(loss_sum, sdata[0] / static_cast<float>(n));
    }
}
torch::Tensor triplet_margin_loss_cuda(
    torch::Tensor anchor,
    torch::Tensor positive,
    torch::Tensor negative,
    float margin)
{
    const int batch_size = anchor.size(0);
    const int dim = anchor.size(1);
    auto per_row_loss = torch::empty({batch_size}, anchor.options());
    auto loss_sum = torch::zeros({1}, anchor.options());
    dim3 grid(batch_size);
    dim3 block(BLOCK_SIZE);
    triplet_margin_loss_kernel<<<grid, block>>>(
        anchor.data_ptr<float>(),
        positive.data_ptr<float>(),
        negative.data_ptr<float>(),
        per_row_loss.data_ptr<float>(),
        batch_size,
        dim,
        margin
    );
    int reduce_grid = (batch_size + REDUCE_BLOCK_SIZE - 1) / REDUCE_BLOCK_SIZE;
    if (reduce_grid > 4096) reduce_grid = 4096;
    if (reduce_grid < 1) reduce_grid = 1;
    reduce_sum_kernel<<<reduce_grid, REDUCE_BLOCK_SIZE>>>(
        per_row_loss.data_ptr<float>(),
        loss_sum.data_ptr<float>(),
        batch_size
    );
    return loss_sum.squeeze();
}
"""

