    batch_size = 32768
    input_shape = (8192,)
    scale = torch.rand(())
    return [torch.rand(batch_size, *input_shape).cuda() * scale,
            torch.rand(batch_size, *input_shape).cuda(),
            torch.rand(batch_size, *input_shape).cuda()]


def get_init_inputs():
    return [1.0]

