    Optimized model that computes Triplet Margin Loss using a custom fused CUDA kernel.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = margin
        self.triplet_loss = triplet_loss_module

    def forward(self, anchor, positive, negative):
        anchor = anchor.contiguous()
        positive = positive.contiguous()
        negative = negative.contiguous()
        return self.triplet_loss.triplet_margin_loss_cuda(anchor, positive, negative, self.margin)


